	"os"

	goredis "github.com/redis/go-redis/v9"
	"go.flipt.io/flipt/internal/config"
)

// caBundle resolves the extra certificate authorities to trust for a Redis
// TLS connection. Inline bytes take precedence over a file path. When neither
// option is configured it returns no bundle and no error, leaving the client
// to fall back to the system certificate authorities.
func caBundle(cfg config.RedisCacheConfig) ([]byte, error) {
	if cfg.CaCertBytes != "" {
		return []byte(cfg.CaCertBytes), nil
	}

	if cfg.CaCertPath != "" {
		bundle, err := os.ReadFile(cfg.CaCertPath)
		if err != nil {
			return nil, fmt.Errorf("reading redis ca certificate %q: %w", cfg.CaCertPath, err)
		}

		return bundle, nil
	}

	return nil, nil
}

// NewClient constructs a Redis client from the supplied cache configuration.
//
// When RequireTLS is set the connection uses TLS 1.2 or newer. A custom
// certificate authority may be supplied inline or by path; it is added to the
// system certificate pool. Setting InsecureSkipTLS disables verification of
// the server certificate.
func NewClient(cfg config.RedisCacheConfig) (*goredis.Client, error) {
	opts := &goredis.Options{
		Addr:            fmt.Sprintf("%s:%d", cfg.Host, cfg.Port),
		Username:        cfg.Username,
		Password:        cfg.Password,
		DB:              cfg.DB,
		PoolSize:        cfg.PoolSize,
		MinIdleConns:    cfg.MinIdleConn,
		ConnMaxIdleTime: cfg.ConnMaxIdleTime,
		DialTimeout:     cfg.NetTimeout,
		ReadTimeout:     cfg.NetTimeout * 2,
		WriteTimeout:    cfg.NetTimeout * 2,
		PoolTimeout:     cfg.NetTimeout * 2,
	}

	if cfg.RequireTLS {
		tlsConfig := &tls.Config{
			MinVersion:         tls.VersionTLS12,
			InsecureSkipVerify: cfg.InsecureSkipTLS,
		}

		bundle, err := caBundle(cfg)
		if err != nil {
			return nil, err
		}

		if len(bundle) > 0 {
			pool, err := x509.SystemCertPool()
			if err != nil {
				return nil, fmt.Errorf("loading system certificate pool: %w", err)
			}

			pool.AppendCertsFromPEM(bundle)
			tlsConfig.RootCAs = pool
		}

		opts.TLSConfig = tlsConfig
	}

	return goredis.NewClient(opts), nil
}
EOF
